/* StockWise App */
const SW={version:'1.8.0',showToast(t,m='',type='info'){const c=document.getElementById('toastContainer');if(!c)return;const el=document.createElement('div');el.className='toast '+type;el.innerHTML='<strong>'+t+'</strong>'+(m?'<div class="text-muted" style="font-size:.85rem;margin-top:2px">'+m+'</div>':'');c.appendChild(el);setTimeout(()=>el.remove(),3500)}};
function openModal(title,body){document.getElementById('modalTitle').textContent=title;document.getElementById('modalBody').innerHTML=body;document.getElementById('modalOverlay').classList.remove('hidden')}
function closeModal(){document.getElementById('modalOverlay').classList.add('hidden')}
document.addEventListener('DOMContentLoaded',()=>{
  document.getElementById('themeToggle')?.addEventListener('click',()=>{const d=document.documentElement;const n=d.getAttribute('data-theme')==='dark'?'light':'dark';d.setAttribute('data-theme',n);SW.showToast('Theme',n+' mode','info')});
  document.getElementById('modalClose')?.addEventListener('click',closeModal);
  document.getElementById('modalOverlay')?.addEventListener('click',e=>{if(e.target.id==='modalOverlay')closeModal()});
  document.querySelectorAll('.tab-btn').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('.tab-btn').forEach(x=>x.classList.remove('active'));document.querySelectorAll('.tab-content').forEach(x=>x.classList.remove('active'));b.classList.add('active');document.getElementById('tab-'+b.dataset.tab)?.classList.add('active')}));
  document.querySelectorAll('form[data-validate]').forEach(f=>f.addEventListener('submit',e=>{e.preventDefault();SW.showToast('Success','Saved successfully','success');closeModal();f.reset()}));
});
